Ui.Script:
NUM_WORLDMAP_DETAIL_TILES = 12;
NUM_WORLDMAP_OVERLAYS = 0;

function ToggleWorldMap()
    if ( WorldMapFrame:IsVisible() ) then
        WorldMapFrame:Hide();
    else
        WorldMapFrame:Show();
    end
end

-- Fill the screen: scale the native 1024×768 sheet up until it touches the constraining
-- screen edge — full height on any screen wider than 4:3 (the common case), full width on
-- a narrower one (ref SetupFullscreenScale, deferred at 0203, wired at 0224). The blackout
-- is a SEPARATE unscaled frame behind the sheet, so only the sheet grows.
function SetupFullscreenScale()
    local xScale = GetScreenWidth() / 1024;
    local yScale = GetScreenHeight() / 768;
    local scale = xScale;
    if ( yScale < xScale ) then
        scale = yScale;
    end
    WorldMapFrame:SetScale(scale);
end

-- ref-WorldMapFrame.lua WorldMapFrame_Update(): the tile swap, the discovery-overlay
-- pool, and the zoom-out arming (POI landmarks are still deferred). The "World" fallback
-- is the reference's own hack for the nil GetMapInfo at the world level — kept verbatim.
function WorldMapFrame_Update()
    local mapFileName = GetMapInfo();
    if ( not mapFileName ) then
        mapFileName = "World";
    end
    for i=1, NUM_WORLDMAP_DETAIL_TILES, 1 do
        getglobal("WorldMapDetailTile"..i):SetTexture("Interface\\WorldMap\\"..mapFileName.."\\"..mapFileName..i);
    end

    -- The discovery overlays (ref WorldMapFrame.lua:94-153): the base tiles are the
    -- unexplored parchment; each REVEALED sub-area (GetNumMapOverlays / GetMapOverlayInfo,
    -- filtered host-side by the explored bitset) paints its detailed art on top. Pool
    -- ARTWORK textures on WorldMapDetailFrame on demand, slice each overlay into 256-px
    -- tiles whose file sizes round up to the next power of two, park the leftovers hidden.
    -- Native offsets — the map renders at its native 1024×768 (no WORLDMAP_SX/SY scale,
    -- unlike the parked windowed layout); the overlays share the detail tiles' coord space.
    local numOverlays = GetNumMapOverlays();
    local textureName, textureWidth, textureHeight, offsetX, offsetY;
    local textureCount = 0;
    local texture;
    local texturePixelWidth, textureFileWidth, texturePixelHeight, textureFileHeight;
    local numTexturesWide, numTexturesTall, neededTextures;
    for i=1, numOverlays do
        textureName, textureWidth, textureHeight, offsetX, offsetY = GetMapOverlayInfo(i);
        numTexturesWide = ceil(textureWidth/256);
        numTexturesTall = ceil(textureHeight/256);
        neededTextures = textureCount + (numTexturesWide * numTexturesTall);
        if ( neededTextures > NUM_WORLDMAP_OVERLAYS ) then
            for j=NUM_WORLDMAP_OVERLAYS+1, neededTextures do
                WorldMapDetailFrame:CreateTexture("WorldMapOverlay"..j, "ARTWORK");
            end
            NUM_WORLDMAP_OVERLAYS = neededTextures;
        end
        for j=1, numTexturesTall do
            if ( j < numTexturesTall ) then
                texturePixelHeight = 256;
                textureFileHeight = 256;
            else
                texturePixelHeight = mod(textureHeight, 256);
                if ( texturePixelHeight == 0 ) then
                    texturePixelHeight = 256;
                end
                textureFileHeight = 16;
                while(textureFileHeight < texturePixelHeight) do
                    textureFileHeight = textureFileHeight * 2;
                end
            end
            for k=1, numTexturesWide do
                textureCount = textureCount + 1;
                texture = getglobal("WorldMapOverlay"..textureCount);
                if ( k < numTexturesWide ) then
                    texturePixelWidth = 256;
                    textureFileWidth = 256;
                else
                    texturePixelWidth = mod(textureWidth, 256);
                    if ( texturePixelWidth == 0 ) then
                        texturePixelWidth = 256;
                    end
                    textureFileWidth = 16;
                    while(textureFileWidth < texturePixelWidth) do
                        textureFileWidth = textureFileWidth * 2;
                    end
                end
                texture:SetWidth(texturePixelWidth);
                texture:SetHeight(texturePixelHeight);
                texture:SetTexCoord(0, texturePixelWidth/textureFileWidth, 0, texturePixelHeight/textureFileHeight);
                texture:ClearAllPoints();
                texture:SetPoint("TOPLEFT", offsetX + (256 * (k-1)), -(offsetY + (256 * (j - 1))));
                texture:SetTexture(textureName..(((j - 1) * numTexturesWide) + k));
                texture:Show();
            end
        end
    end
    for i=textureCount+1, NUM_WORLDMAP_OVERLAYS do
        getglobal("WorldMapOverlay"..i):Hide();
    end

    if ( GetCurrentMapContinent() == 0 ) then
        WorldMapZoomOutButton:Disable();
    else
        WorldMapZoomOutButton:Enable();
    end
end

-- ref verbatim: zone view → its continent; continent view → the world.
function WorldMapZoomOutButton_OnClick()
    if ( GetCurrentMapZone() ~= 0 ) then
        SetMapZoom(GetCurrentMapContinent());
    else
        SetMapZoom(0);
    end
end

-- ── The continent/zone dropdowns (ref verbatim, except the vararg walk: the reference's
-- `arg.n` needs LUA_COMPAT_VARARG, which stock 5.1 — and ours — doesn't ship; select()
-- is the 5.1-native spelling). ─────────────────────────────────────────────────────────
function WorldMapContinentsDropDown_OnLoad()
    UIDropDownMenu_Initialize(this, WorldMapContinentsDropDown_Initialize);
    UIDropDownMenu_SetWidth(130);
end

function WorldMapContinentsDropDown_Initialize()
    WorldMapFrame_LoadContinents(GetMapContinents());
end

function WorldMapFrame_LoadContinents(...)
    local info;
    for i=1, select("#", ...), 1 do
        info = {};
        info.text = select(i, ...);
        info.func = WorldMapContinentButton_OnClick;
        UIDropDownMenu_AddButton(info);
    end
end

function WorldMapZoneDropDown_OnLoad()
    UIDropDownMenu_Initialize(this, WorldMapZoneDropDown_Initialize);
    UIDropDownMenu_SetWidth(130);
end

function WorldMapZoneDropDown_Initialize()
    WorldMapFrame_LoadZones(GetMapZones(GetCurrentMapContinent()));
end

function WorldMapFrame_LoadZones(...)
    local info;
    for i=1, select("#", ...), 1 do
        info = {};
        info.text = select(i, ...);
        info.func = WorldMapZoneButton_OnClick;
        UIDropDownMenu_AddButton(info);
    end
end

function WorldMapContinentButton_OnClick()
    UIDropDownMenu_SetSelectedID(WorldMapContinentDropDown, this:GetID());
    SetMapZoom(this:GetID());
end

function WorldMapZoneButton_OnClick()
    UIDropDownMenu_SetSelectedID(WorldMapZoneDropDown, this:GetID());
    SetMapZoom(GetCurrentMapContinent(), this:GetID());
end

function WorldMap_UpdateZoneDropDownText()
    if ( GetCurrentMapZone() == 0 ) then
        UIDropDownMenu_ClearAll(WorldMapZoneDropDown);
    else
        UIDropDownMenu_SetSelectedID(WorldMapZoneDropDown, GetCurrentMapZone());
    end
end

function WorldMap_UpdateContinentDropDownText()
    if ( GetCurrentMapContinent() == 0 ) then
        UIDropDownMenu_ClearAll(WorldMapContinentDropDown);
    else
        UIDropDownMenu_SetSelectedID(WorldMapContinentDropDown, GetCurrentMapContinent());
    end
end

-- ref verbatim: left click drills in via ProcessMapClick on normalized button coords;
-- anything else zooms out.
function WorldMapButton_OnClick(mouseButton)
    CloseDropDownMenus();
    if ( mouseButton == "LeftButton" ) then
        local x, y = GetCursorPosition();
        x = x / WorldMapButton:GetEffectiveScale();
        y = y / WorldMapButton:GetEffectiveScale();
        local centerX, centerY = WorldMapButton:GetCenter();
        local width = WorldMapButton:GetWidth();
        local height = WorldMapButton:GetHeight();
        local adjustedY = (centerY + (height/2) - y) / height;
        local adjustedX = (x - (centerX - (width/2))) / width;
        ProcessMapClick( adjustedX, adjustedY);
    else
        WorldMapZoomOutButton_OnClick();
    end
end

-- ref WorldMapButton_OnUpdate, reduced to hover + the player blip (party/raid/flags/
-- corpse/ping are deferred with their wire). UpdateMapHighlight is a stub until the
-- area-bitmap source lands (wow-re dispatch) — nil name/fileName take the hide paths.
function WorldMapButton_OnUpdate(elapsed)
    local x, y = GetCursorPosition();
    x = x / this:GetEffectiveScale();
    y = y / this:GetEffectiveScale();
    local centerX, centerY = this:GetCenter();
    local width = this:GetWidth();
    local height = this:GetHeight();
    local adjustedY = (centerY + (height/2) - y ) / height;
    local adjustedX = (x - (centerX - (width/2))) / width;
    local name, fileName, texPercentageX, texPercentageY, textureX, textureY, scrollChildX, scrollChildY = UpdateMapHighlight( adjustedX, adjustedY );
    WorldMapFrameAreaLabel:SetText(name or "");
    if ( fileName ) then
        WorldMapHighlight:SetTexCoord(0, texPercentageX, 0, texPercentageY);
        WorldMapHighlight:SetTexture("Interface\\WorldMap\\"..fileName.."\\"..fileName.."Highlight");
        textureX = textureX * width;
        textureY = textureY * height;
        scrollChildX = scrollChildX * width;
        scrollChildY = -scrollChildY * height;
        if ( (textureX > 0) and (textureY > 0) ) then
            WorldMapHighlight:SetWidth(textureX);
            WorldMapHighlight:SetHeight(textureY);
            WorldMapHighlight:SetPoint("TOPLEFT", "WorldMapDetailFrame", "TOPLEFT", scrollChildX, scrollChildY);
            WorldMapHighlight:Show();
        end
    else
        WorldMapHighlight:Hide();
    end
    -- The player blip: the reference's engine arrow, as our rotating texture stand-in.
    WorldMapPlayerIcon:SetRotation(GetPlayerFacing());
    local playerX, playerY = GetPlayerMapPosition("player");
    if ( playerX == 0 and playerY == 0 ) then
        WorldMapPlayer:Hide();
    else
        playerX = playerX * WorldMapDetailFrame:GetWidth();
        playerY = -playerY * WorldMapDetailFrame:GetHeight();
        WorldMapPlayer:SetPoint("CENTER", "WorldMapDetailFrame", "TOPLEFT", playerX, playerY);
        WorldMapPlayer:Show();
    end
    -- Position corpse (ref WorldMapFrame.lua:443-452, verbatim law: (0,0) = hide).
    local corpseX, corpseY = GetCorpseMapPosition();
    if ( corpseX == 0 and corpseY == 0 ) then
        WorldMapCorpse:Hide();
    else
        corpseX = corpseX * WorldMapDetailFrame:GetWidth();
        corpseY = -corpseY * WorldMapDetailFrame:GetHeight();
        WorldMapCorpse:SetPoint("CENTER", "WorldMapDetailFrame", "TOPLEFT", corpseX, corpseY);
        WorldMapCorpse:Show();
    end
end

Scripts.OnEvent:
if ( this:IsVisible() ) then
    WorldMapContinentsDropDown_OnLoad();
    WorldMap_UpdateContinentDropDownText();
    WorldMapZoneDropDown_OnLoad();
    WorldMap_UpdateZoneDropDownText();
end

Scripts.OnLoad:
this:RegisterEvent("WORLD_MAP_UPDATE");
-- The hover area label inherits WorldMapTextFont (nominal 102). 33 was the
-- director's taste call (0235) — which the one-to-one raster cap (the fold-back
-- record; wow-re fontstring-overflow.md) now clamps to the byte law's 32, one
-- unit under that call and closer to it than the 36 the atlas snap used to
-- deliver. The real client draws this SetFont(33) at 32 too. Still a taste dial:
-- any value ≤ 32 is honored exactly.
WorldMapFrameAreaLabel:SetFont("Fonts\\FRIZQT__.TTF", 33);
WorldMapFrame_Update();

Scripts.OnShow:
WorldMapBlackout:Show();
SetupFullscreenScale();
SetMapToCurrentZone();
WorldMapFrame_Update();
PlaySound("igQuestLogOpen");
CloseDropDownMenus();
